const firstItem = $input.first()?.json || {};
const body = firstItem.body || firstItem.query || firstItem;

// 1. Detección de origen: Cron de vigilancia autónoma vs Webhook/Telegram
const isScheduled = Boolean(firstItem.timestamp && !firstItem.headers && !body.message && !body.callback_query && !body.ticker && !body.mode);
const triggerSource = isScheduled ? 'schedule' : 'webhook';
const telegramChatId = String(
  body.callback_query?.message?.chat?.id ||
  body.message?.chat?.id ||
  body.chat_id ||
  '5900371156'
);

// 2. Almacenamiento persistente del usuario (Global Workflow Static Data)
let staticData = {};
try {
  staticData = $getWorkflowStaticData('global');
} catch (e) {
  staticData = {};
}

if (!staticData.v2_clean_initialized) {
  staticData.accountSize = 10000; // $10,000 USD default
  staticData.riskPercent = 1.0;   // 1% riesgo por trade
  staticData.watchlist = [];      // Inicia completamente vacío
  staticData.positions = [];      // Inicia completamente vacío
  staticData.processedCallbackIds = [];
  staticData.v2_clean_initialized = true;
  staticData.initialized = true;
}

if (!Array.isArray(staticData.watchlist)) staticData.watchlist = [];
if (!Array.isArray(staticData.positions)) staticData.positions = [];

// 3. De-duplicación y respuesta rápida a callbacks de Telegram
if (body.callback_query) {
  const cbId = String(body.callback_query.id || '');
  const cbData = String(body.callback_query.data || '');
  const now = Date.now();

  if (cbId) {
    try {
      fetch('https://api.telegram.org/bot8923613669:AAG8CHP09iybu_B47XUPsMeeMdj-rURX9Ds/answerCallbackQuery', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ callback_query_id: cbId })
      }).catch(() => {});
    } catch (e) {}
  }

  if (staticData.processedCallbackIds && staticData.processedCallbackIds.includes(cbId)) {
    return [];
  }
  if (staticData.lastCallbackData === cbData && (now - (staticData.lastCallbackTime || 0)) < 3500) {
    return [];
  }

  if (!Array.isArray(staticData.processedCallbackIds)) staticData.processedCallbackIds = [];
  staticData.processedCallbackIds.push(cbId);
  if (staticData.processedCallbackIds.length > 50) staticData.processedCallbackIds.shift();

  staticData.lastCallbackData = cbData;
  staticData.lastCallbackTime = now;
}

// 4. Extraer texto o comando
let rawText = String(
  body.callback_query?.data ||
  body.message?.text ||
  body.ticker ||
  body.symbol ||
  body.text ||
  ''
).trim();

let cleanInput = rawText.toUpperCase();
if (cleanInput.startsWith('/')) {
  cleanInput = cleanInput.substring(1).trim();
}

// Helper para normalizar símbolos populares
const normalizeTicker = (t) => {
  let sym = (t || '').toUpperCase().trim();
  if (sym === 'EURUSD') return 'EURUSD=X';
  if (sym === 'GBPUSD') return 'GBPUSD=X';
  if (sym === 'USDJPY') return 'USDJPY=X';
  if (sym === 'AUDUSD') return 'AUDUSD=X';
  if (sym === 'BTC' || sym === 'BITCOIN') return 'BTC-USD';
  if (sym === 'ETH' || sym === 'ETHEREUM') return 'ETH-USD';
  if (sym === 'SOL' || sym === 'SOLANA') return 'SOL-USD';
  if (sym === 'ORO' || sym === 'GOLD' || sym === 'XAUUSD') return 'GC=F';
  if (sym === 'PETROLEO' || sym === 'OIL') return 'CL=F';
  if (sym === 'PLATA' || sym === 'SILVER') return 'SI=F';
  return sym;
};

// ============================================================================
// A. DISPARO AUTÓNOMO PROGRAMADO (VIGILANTE CRON CADA 15 MINUTOS)
// REGLA CRUCIAL: SOLO VIGILA LO QUE EL USUARIO REGISTRÓ (COMPRAS O VIGILANCIA).
// SI ESTÁ VACÍO, RETORNA [] (0 MENSAJES, 0 ALERTAS FANTASMA).
// ============================================================================
if (isScheduled) {
  const activeSymbols = Array.from(new Set([
    ...staticData.watchlist,
    ...staticData.positions.map(p => p.symbol)
  ]));

  if (activeSymbols.length === 0) {
    return [];
  }

  return activeSymbols.map(symbol => {
    const pos = staticData.positions.find(p => p.symbol === symbol) || null;
    return {
      json: {
        ticker: symbol,
        mode: 'scheduled_scan',
        triggerSource,
        telegramChatId,
        accountSize: staticData.accountSize,
        riskPercent: staticData.riskPercent,
        position: pos,
        allPositions: staticData.positions,
        watchlist: staticData.watchlist
      }
    };
  });
}

// ============================================================================
// B. CONFIGURAR SALDO/CAPITAL DE LA CUENTA (Ej: "CAPITAL 5000", "CUENTA 20000")
// ============================================================================
if (cleanInput.startsWith('CAPITAL') || cleanInput.startsWith('CUENTA') || cleanInput.startsWith('SALDO')) {
  const parts = cleanInput.split(/[\s,:]+/).filter(Boolean);
  const amount = parseFloat(parts[1]?.replace('$', ''));
  if (amount && !isNaN(amount) && amount > 0) {
    staticData.accountSize = amount;
    const dollarRisk = (staticData.accountSize * staticData.riskPercent / 100).toFixed(2);
    return [{
      json: {
        ticker: 'EURUSD=X',
        mode: 'config_success',
        configMsg: `✅ *CAPITAL CONFIGURADO CON ÉXITO*\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n💵 *Saldo de Cuenta:* $${amount.toLocaleString('en-US')} USD\n⚖️ *Riesgo Configurado:* ${staticData.riskPercent}% ($${dollarRisk} USD por trade)`,
        triggerSource,
        telegramChatId,
        accountSize: staticData.accountSize,
        riskPercent: staticData.riskPercent,
        positions: staticData.positions,
        watchlist: staticData.watchlist
      }
    }];
  }
}

// ============================================================================
// C. CONFIGURAR RIESGO PORCENTUAL (Ej: "RIESGO 1", "RIESGO 1.5%", "RISK 2")
// ============================================================================
if (cleanInput.startsWith('RIESGO') || cleanInput.startsWith('RISK')) {
  const parts = cleanInput.split(/[\s,:%]+/).filter(Boolean);
  const pct = parseFloat(parts[1]);
  if (pct && !isNaN(pct) && pct > 0 && pct <= 10) {
    staticData.riskPercent = pct;
    const dollarRisk = (staticData.accountSize * pct / 100).toFixed(2);
    return [{
      json: {
        ticker: 'EURUSD=X',
        mode: 'config_success',
        configMsg: `✅ *RIESGO POR TRADE ACTUALIZADO*\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n⚖️ *Riesgo:* ${pct}%\n💵 *Pérdida Máxima por SL:* $${dollarRisk} USD\n(Basado en tu capital de $${staticData.accountSize.toLocaleString('en-US')} USD)`,
        triggerSource,
        telegramChatId,
        accountSize: staticData.accountSize,
        riskPercent: staticData.riskPercent,
        positions: staticData.positions,
        watchlist: staticData.watchlist
      }
    }];
  }
}

// ============================================================================
// D. REGISTRAR COMPRA / POSICIÓN CON MONTO Y PRECIO
// Ejemplos:
// "COMPRAR NVDA 120 1000" (Ticker: NVDA, Precio compra: 120, Monto invertido: 1000 USD)
// "COMPRA BTC-USD 60000 500"
// "AGREGAR AAPL 220 1500"
// ============================================================================
if (cleanInput.startsWith('COMPRAR') || cleanInput.startsWith('COMPRA') || cleanInput.startsWith('POSICION') || (cleanInput.startsWith('AGREGAR') && cleanInput.split(/\s+/).length >= 4)) {
  const rest = cleanInput.replace(/^(COMPRAR|COMPRA|POSICION|AGREGAR)\s+/i, '').trim();
  const parts = rest.split(/[\s,]+/).filter(Boolean);
  const rawTicker = parts[0] || '';
  const ticker = normalizeTicker(rawTicker);
  const buyPrice = parseFloat(parts[1]?.replace('$', ''));
  const amountUsd = parseFloat(parts[2]?.replace('$', ''));

  if (ticker && buyPrice && amountUsd && !isNaN(buyPrice) && !isNaN(amountUsd) && buyPrice > 0 && amountUsd > 0) {
    const shares = amountUsd / buyPrice;
    const existingIndex = staticData.positions.findIndex(p => p.symbol === ticker);
    const newPos = {
      symbol: ticker,
      buyPrice,
      amountUsd,
      shares,
      addedAt: new Date().toISOString().split('T')[0]
    };

    if (existingIndex >= 0) {
      staticData.positions[existingIndex] = newPos;
    } else {
      staticData.positions.push(newPos);
    }

    if (!staticData.watchlist.includes(ticker)) {
      staticData.watchlist.push(ticker);
    }

    return [{
      json: {
        ticker,
        mode: 'position_success',
        configMsg: `✅ *COMPRA REGISTRADA PARA VIGILANCIA*\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n📌 *Activo:* \`${ticker}\`\n💲 *Precio de Entrada:* $${buyPrice.toLocaleString('en-US')}\n💰 *Monto Invertido:* $${amountUsd.toLocaleString('en-US')} USD\n📊 *Títulos / Unidades:* ${shares.toFixed(4)}\n\n🛡️ *El Vigilante Autónomo supervisará:*\n• Descenso de precio bajo Stop Loss (5m)\n• Ratio 1:1 para mover a Break Even (BE)\n• Take Profit en lo alto de vela impulsiva`,
        triggerSource,
        telegramChatId,
        accountSize: staticData.accountSize,
        riskPercent: staticData.riskPercent,
        position: newPos,
        positions: staticData.positions,
        watchlist: staticData.watchlist
      }
    }];
  }
}

// ============================================================================
// E. AGREGAR SOLO ACTIVO EN VIGILANCIA (Sin compra previa)
// Ej: "VIGILAR TSLA", "AGREGAR EURUSD=X", "VIGILAR BTC-USD"
// ============================================================================
if (cleanInput.startsWith('VIGILAR') || (cleanInput.startsWith('AGREGAR') && cleanInput.split(/\s+/).length < 4) || cleanInput.startsWith('WATCH')) {
  const rest = cleanInput.replace(/^(VIGILAR|AGREGAR|WATCH)\s+/i, '').trim();
  const parts = rest.split(/[\s,]+/).filter(Boolean);
  const rawTicker = parts[0] || '';
  const ticker = normalizeTicker(rawTicker);

  if (ticker && ticker.length >= 2) {
    if (!staticData.watchlist.includes(ticker)) {
      staticData.watchlist.push(ticker);
    }
    return [{
      json: {
        ticker,
        mode: 'watchlist_success',
        configMsg: `✅ *ACTIVO AGREGADO A LA VIGILANCIA*\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n📌 *Activo:* \`${ticker}\`\n\nEl Vigilante Autónomo revisará este activo cada 15m buscando gatillos de entrada Bard.fx (No Wick / Vela sin mecha + mitigación a 5m).`,
        triggerSource,
        telegramChatId,
        accountSize: staticData.accountSize,
        riskPercent: staticData.riskPercent,
        positions: staticData.positions,
        watchlist: staticData.watchlist
      }
    }];
  }
}

// ============================================================================
// F. VER MI PORTAFOLIO Y COMPRAS (Botón o comando /portafolio)
// ============================================================================
if (cleanInput === 'PORTAFOLIO' || cleanInput === 'CARTERA' || cleanInput === 'MIS ACTIVOS' || cleanInput === 'COMPRAS' || cleanInput === 'POSICIONES' || cleanInput === 'MY_PORTFOLIO') {
  const activeSymbols = Array.from(new Set([
    ...staticData.watchlist,
    ...staticData.positions.map(p => p.symbol)
  ]));

  if (activeSymbols.length === 0) {
    return [{
      json: {
        ticker: 'EURUSD=X',
        mode: 'portfolio_empty',
        triggerSource,
        telegramChatId,
        accountSize: staticData.accountSize,
        riskPercent: staticData.riskPercent,
        positions: [],
        watchlist: []
      }
    }];
  }

  return activeSymbols.map(symbol => {
    const pos = staticData.positions.find(p => p.symbol === symbol) || null;
    return {
      json: {
        ticker: symbol,
        mode: 'portfolio_view',
        triggerSource,
        telegramChatId,
        accountSize: staticData.accountSize,
        riskPercent: staticData.riskPercent,
        position: pos,
        allPositions: staticData.positions,
        watchlist: staticData.watchlist
      }
    };
  });
}

// ============================================================================
// G. ELIMINAR / QUITAR ACTIVO O POSICIÓN
// ============================================================================
if (cleanInput.startsWith('QUITAR') || cleanInput.startsWith('ELIMINAR') || cleanInput.startsWith('BORRAR') || cleanInput.startsWith('VENDER')) {
  if (cleanInput.includes('TODO') || cleanInput.includes('ALL') || cleanInput.includes('LIMPIAR')) {
    staticData.positions = [];
    staticData.watchlist = [];
    return [{
      json: {
        ticker: 'EURUSD=X',
        mode: 'clear_success',
        configMsg: `🗑️ *PORTAFOLIO Y VIGILANCIA VACIADOS*\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nSe han eliminado todas las compras y activos.\n⏸️ *El Vigilante Autónomo entra en PAUSA* y no emitirá ninguna alerta hasta que agregues nuevos activos.`,
        triggerSource,
        telegramChatId,
        accountSize: staticData.accountSize,
        riskPercent: staticData.riskPercent,
        positions: [],
        watchlist: []
      }
    }];
  }

  const rest = cleanInput.replace(/^(QUITAR|ELIMINAR|BORRAR|VENDER)\s+/i, '').trim();
  const ticker = normalizeTicker(rest.split(/[\s,]+/)[0]);

  if (ticker) {
    staticData.positions = staticData.positions.filter(p => p.symbol !== ticker);
    staticData.watchlist = staticData.watchlist.filter(w => w !== ticker);
    return [{
      json: {
        ticker: 'EURUSD=X',
        mode: 'config_success',
        configMsg: `🗑️ *ACTIVO RETIRADO:* \`${ticker}\`\nYa no recibirás alertas sobre este activo.\nActivos restantes en vigilancia: ${staticData.watchlist.length > 0 ? staticData.watchlist.map(w => '`' + w + '`').join(', ') : '_Ninguno (Vigilante en pausa)_'}`,
        triggerSource,
        telegramChatId,
        accountSize: staticData.accountSize,
        riskPercent: staticData.riskPercent,
        positions: staticData.positions,
        watchlist: staticData.watchlist
      }
    }];
  }
}

// ============================================================================
// H. LIMPIAR TODO
// ============================================================================
if (cleanInput === 'LIMPIAR' || cleanInput === 'VACIAR') {
  staticData.positions = [];
  staticData.watchlist = [];
  return [{
    json: {
      ticker: 'EURUSD=X',
      mode: 'clear_success',
      configMsg: `🗑️ *PORTAFOLIO Y VIGILANCIA VACIADOS*\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n⏸️ *El Vigilante Autónomo está en pausa*. No enviará alertas hasta que agregues activos o compras.`,
      triggerSource,
      telegramChatId,
      accountSize: staticData.accountSize,
      riskPercent: staticData.riskPercent,
      positions: [],
      watchlist: []
    }
  }];
}

// ============================================================================
// I. GUÍA ¿CÓMO AGREGAR COMPRAS O ACTIVOS?
// ============================================================================
if (cleanInput === 'COMO_AGREGAR' || cleanInput === 'AYUDA_COMPRA') {
  return [{
    json: {
      ticker: 'EURUSD=X',
      mode: 'how_to_add',
      triggerSource,
      telegramChatId,
      accountSize: staticData.accountSize,
      riskPercent: staticData.riskPercent,
      positions: staticData.positions,
      watchlist: staticData.watchlist
    }
  }];
}

// ============================================================================
// J. ESCANEAR AHORA MANUALMENTE
// ============================================================================
if (cleanInput === 'SCAN_NOW' || cleanInput === 'ESCANEAR') {
  const activeSymbols = Array.from(new Set([
    ...staticData.watchlist,
    ...staticData.positions.map(p => p.symbol)
  ]));

  if (activeSymbols.length === 0) {
    return [{
      json: {
        ticker: 'EURUSD=X',
        mode: 'portfolio_empty',
        triggerSource,
        telegramChatId,
        accountSize: staticData.accountSize,
        riskPercent: staticData.riskPercent,
        positions: [],
        watchlist: []
      }
    }];
  }

  return activeSymbols.map(symbol => {
    const pos = staticData.positions.find(p => p.symbol === symbol) || null;
    return {
      json: {
        ticker: symbol,
        mode: 'manual_scan',
        triggerSource,
        telegramChatId,
        accountSize: staticData.accountSize,
        riskPercent: staticData.riskPercent,
        position: pos,
        allPositions: staticData.positions,
        watchlist: staticData.watchlist
      }
    };
  });
}

// ============================================================================
// K. GUÍA DE ESTRATEGIA BARD.FX
// ============================================================================
if (cleanInput === 'ESTRATEGIA' || cleanInput === 'REGLAS' || cleanInput === 'BARDFX') {
  return [{
    json: {
      ticker: 'EURUSD=X',
      mode: 'strategy_guide',
      triggerSource,
      telegramChatId,
      accountSize: staticData.accountSize,
      riskPercent: staticData.riskPercent,
      positions: staticData.positions,
      watchlist: staticData.watchlist
    }
  }];
}

// ============================================================================
// L. MENÚ PRINCIPAL
// ============================================================================
if (!cleanInput || cleanInput === 'START' || cleanInput === 'MENU' || cleanInput === 'AYUDA' || cleanInput === 'HELP') {
  return [{
    json: {
      ticker: 'EURUSD=X',
      mode: 'menu',
      triggerSource,
      telegramChatId,
      accountSize: staticData.accountSize,
      riskPercent: staticData.riskPercent,
      positions: staticData.positions,
      watchlist: staticData.watchlist
    }
  }];
}

// ============================================================================
// M. ANÁLISIS INDIVIDUAL DE CUALQUIER ACTIVO
// ============================================================================
const analyzedTicker = normalizeTicker(cleanInput);
return [{
  json: {
    ticker: analyzedTicker,
    mode: 'single_trade',
    triggerSource,
    telegramChatId,
    accountSize: staticData.accountSize,
    riskPercent: staticData.riskPercent,
    position: staticData.positions.find(p => p.symbol === analyzedTicker) || null,
    positions: staticData.positions,
    watchlist: staticData.watchlist
  }
}];

