const mode = firstRoute.mode || 'menu';
const triggerSource = firstRoute.triggerSource || 'webhook';
const telegramChatId = firstRoute.telegramChatId || '5900371156';
const accountSize = Number(firstRoute.accountSize || 10000);
const riskPercent = Number(firstRoute.riskPercent || 1.0);
const riskAmountUsd = Number(((accountSize * riskPercent) / 100).toFixed(2));

// Teclado interactivo para Telegram
const inlineKeyboard = [
  [
    { text: '💼 Mi Portafolio & Compras', callback_data: 'PORTAFOLIO' },
    { text: '🎯 Escanear Ahora', callback_data: 'SCAN_NOW' }
  ],
  [
