  const price = Number(p || 0);
  if (price >= 1000) return '$' + price.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  if (price >= 1) return '$' + price.toFixed(2);
  return '$' + price.toFixed(decimals);
};

// ============================================================================
// 1. RESPUESTAS RÁPIDAS DE CONFIGURACIÓN Y MENSAJES INFORMATIVOS
// ============================================================================
if (mode === 'config_success' || mode === 'position_success' || mode === 'watchlist_success' || mode === 'clear_success') {
  return [{
    json: {
      mode,
      triggerSource,
      telegramChatId,
      telegramMessage: firstRoute.configMsg,
      replyMarkup: { inline_keyboard: inlineKeyboard }
