    '• `COMPRAR NVDA 120 1000` ➔ NVDA comprado a $120 invirtiendo $1,000 USD.',
    '• `COMPRAR BTC-USD 62000 300` ➔ Bitcoin comprado a $62,000 con $300 USD.',
    '• `COMPRAR EURUSD=X 1.0850 1500` ➔ EUR/USD a 1.0850 con $1,500 USD.',
    '',
    '2️⃣ *Solo Vigilar Gatillos (Sin dinero invertido):*',
    'Escribe: `VIGILAR <ACTIVO>`',
    '• `VIGILAR AAPL` o `VIGILAR GC=F` (Oro)',
    '',
    '3️⃣ *Ajustar Capital y Gestión:*',
    '• `CAPITAL 10000` (Define tu capital de cuenta)',
    '• `RIESGO 1` (Define el 1% de riesgo por operación)',
    '',
    '4️⃣ *Eliminar o Limpiar:*',
    '• `QUITAR NVDA` (Remueve de compras y vigilancia)',
    '• `LIMPIAR` (Vacía todo y pausa el Vigilante)'
  ];
  return [{
    json: {
      mode,
      triggerSource,
      telegramChatId,
      telegramMessage: lines.join('\n'),
      replyMarkup: { inline_keyboard: inlineKeyboard }
    }
  }];
}

if (mode === 'strategy_guide') {
  const lines = [
    '📘 *ESTRATEGIA BARD.FX: COMPENSATION PLAY (NO WICK)*',
