// ============================================================================
// HELPER PARA ANALIZAR VELAS DE YAHOO FINANCE
// ============================================================================
const parseYahooCandles = (chartData) => {
  if (!chartData || !chartData.chart || !chartData.chart.result || !chartData.chart.result[0]) return null;
  const result = chartData.chart.result[0];
  const meta = result.meta || {};
  const timestamps = result.timestamp || [];
  const quote = result.indicators?.quote?.[0] || {};
  const opens = quote.open || [];
  const highs = quote.high || [];
  const lows = quote.low || [];
  const closes = quote.close || [];

  const candles = [];
  for (let i = 0; i < timestamps.length; i++) {
    if (closes[i] !== null && opens[i] !== null) {
      candles.push({
        time: timestamps[i],
        open: opens[i],
        high: highs[i],
        low: lows[i],
        close: closes[i],
        range: Math.abs(highs[i] - lows[i]),
        body: Math.abs(closes[i] - opens[i]),
        isBullish: closes[i] >= opens[i]
      });
    }
  }
  if (candles.length === 0) return null;
  const last = candles[candles.length - 1];
  const currentPrice = meta.regularMarketPrice || last.close;
  const prevClose = meta.chartPreviousClose || meta.previousClose || candles[0].close;
  const changePct = Number((((currentPrice - prevClose) / prevClose) * 100).toFixed(2));

  // Análisis Bard.fx No Wick en últimas 15 velas de 5m
  const recent15 = candles.slice(-15);
  let noWickDetected = false;
  let noWickType = null;
  let impulseHigh = Math.max(...recent15.map(c => c.high));
  let impulseLow = Math.min(...recent15.map(c => c.low));
  let mitigationLevel = null;

  for (let i = 0; i < recent15.length - 2; i++) {
    const c = recent15[i];
    if (c.range > 0) {
      if (c.isBullish) {
        const bottomWick = c.open - c.low;
        const wickRatio = bottomWick / c.range;
        if (wickRatio < 0.08) {
          noWickDetected = true;
          noWickType = 'BUY';
          mitigationLevel = c.open;
          impulseHigh = Math.max(impulseHigh, c.high);
          break;
        }
      } else {
        const topWick = c.high - c.open;
        const wickRatio = topWick / c.range;
        if (wickRatio < 0.08) {
          noWickDetected = true;
          noWickType = 'SELL';
          mitigationLevel = c.open;
          impulseLow = Math.min(impulseLow, c.low);
          break;
        }
      }
    }
  }

  // Gatillo 5m actual
  let signal = null;
  const recentLow = Math.min(...candles.slice(-6).map(c => c.low));
  const recentHigh = Math.max(...candles.slice(-6).map(c => c.high));

  if (noWickDetected && noWickType === 'BUY' && currentPrice >= mitigationLevel * 0.998) {
    signal = 'BUY';
  } else if (noWickDetected && noWickType === 'SELL' && currentPrice <= mitigationLevel * 1.002) {
    signal = 'SELL';
  }

  return {
    symbol: meta.symbol || 'ASSET',
    currentPrice,
    changePct,
    noWickDetected,
    noWickType,
    signal,
    recentLow,
    recentHigh,
    impulseHigh,
    impulseLow
  };
};

